// The PWA's generated files: CSS custom properties for the colour roles and surfaces (light,
// dark and forced colours), and an SVG sprite of the glyphs and icons.

import { toCssColor } from './color.mjs';
import { SYSTEM_COLORS, roleTokens, surfaceTokens, monoFamilies, radii, spaces } from './tokens.mjs';
import { MOVING_CLASSES, TOKEN_CLASSES, parts } from './svg.mjs';

export const header = (from) => `Generated by tools/design-gen from ${from}. Do not edit: change design/ and run
   node tools/design-gen/generate.mjs
   CI fails when this file is stale against design/.`;

export function tokensCss(tokens) {
  const roles = roleTokens(tokens);
  const surfaces = surfaceTokens(tokens);
  const block = (list, pick) => list.map((t) => `    ${t.css}: ${pick(t)};`).join('\n');
  return `/* ${header('design/tokens.json')}
   Colour roles and surfaces: docs/design/ui.md §3. Secondary text is text2/text3, never a grey. */

:root {
  /* Light, and every value that doesn't change with the theme. */
${block(roles, (t) => toCssColor(t.light)).replace(/^ {4}/gm, '  ')}
${block(surfaces, (t) => toCssColor(t.light)).replace(/^ {4}/gm, '  ')}

  /* The glyph parts drawn from a token rather than currentColor (design/README.md). The
     knockout is the surface behind the glyph: set it where a glyph sits on another one. */
  --ab-glyph-ink: var(--ab-needs-ink);
  --ab-glyph-knockout: var(--ab-card);
  /* An icon's stroke on its 20 grid: 1.7 at 16 px or below, 1.4 at 24 px or above. */
  --ab-icon-stroke: 1.5;

  --ab-font-mono: ${monoFamilies(tokens, 'css')};
${radii(tokens).map((r) => `  ${r.css}: ${r.value}px;`).join('\n')}
${spaces(tokens).map((s) => `  ${s.css}: ${s.value}px;`).join('\n')}
}

@media (prefers-color-scheme: dark) {
  :root {
${block(roles, (t) => toCssColor(t.dark))}
${block(surfaces, (t) => toCssColor(t.dark))}
  }
}

/* High contrast: every role and surface is a system colour (tokens.json hc). */
@media (forced-colors: active) {
  :root {
${block(roles, (t) => SYSTEM_COLORS[t.hc].css)}
${block(surfaces, (t) => SYSTEM_COLORS[t.hc].css)}
  }
}
`;
}

const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;');

// A part's markup in the sprite: as written, but with token-class colours drawn from the
// token's custom property, which crosses into a <use> where a class selector cannot.
function partMarkup(node, indent) {
  if (node.tag === 'g') {
    const attrs = Object.entries(node.attrs).map(([k, v]) => ` ${k}="${esc(v)}"`).join('');
    return `${indent}<g${attrs}>\n${node.children.map((c) => partMarkup(c, `${indent}  `)).join('\n')}\n${indent}</g>`;
  }
  const token = node.classes.find((c) => c in TOKEN_CLASSES);
  const attrs = Object.entries(node.attrs).map(([k, v]) => {
    if (token && (k === 'fill' || k === 'stroke') && v !== 'none' && v !== 'currentColor') { return ` ${k}="var(--ab-glyph-${TOKEN_CLASSES[token]})"`; }
    return ` ${k}="${esc(v)}"`;
  }).join('');
  return `${indent}<${node.tag}${attrs}/>`;
}

function without(tree, keep) {
  const out = [];
  for (const n of tree) {
    if (n.tag === 'g') {
      const children = without(n.children, keep);
      if (children.length) { out.push({ ...n, children }); }
    } else if (keep(n)) { out.push(n); }
  }
  return out;
}

function symbol(id, svg, tree) {
  const rootAttrs = Object.entries(svg.rootStyle).map(([k, v]) => {
    if (k === 'stroke-width' && svg.kind === 'icon') { return ` ${k}="var(--ab-icon-stroke, ${esc(v)})"`; }
    return ` ${k}="${esc(v)}"`;
  }).join('');
  const body = tree.map((n) => partMarkup(n, '      ')).join('\n');
  return `  <symbol id="${id}" viewBox="0 0 ${svg.size} ${svg.size}">\n    <g${rootAttrs}>\n${body}\n    </g>\n  </symbol>`;
}

// One symbol per glyph and icon (glyph-<name>, icon-<name>). A glyph with a moving part also
// gets <name>--still without it and <name>--spin or --orbit with only it, so a client can
// turn that part alone with CSS on its <use>: rules in this file never reach the page.
export function spriteSvg(glyphs, icons) {
  const symbols = [];
  for (const g of glyphs) {
    symbols.push(symbol(`glyph-${g.name}`, g, g.tree));
    const moving = MOVING_CLASSES.filter((c) => parts(g).some((p) => p.classes.includes(c)));
    if (moving.length) {
      symbols.push(symbol(`glyph-${g.name}--still`, g, without(g.tree, (p) => !p.classes.some((c) => MOVING_CLASSES.includes(c)))));
      for (const c of moving) { symbols.push(symbol(`glyph-${g.name}--${c}`, g, without(g.tree, (p) => p.classes.includes(c)))); }
    }
  }
  for (const i of icons) { symbols.push(symbol(`icon-${i.name}`, i, i.tree)); }
  return `<svg xmlns="http://www.w3.org/2000/svg">
<!-- ${header('design/glyphs/*.svg and design/icons/*.svg')}
   Use: <svg class="..."><use href="design/sprite.svg#glyph-needs"/></svg>, coloured by the
   element's color (currentColor). The ink, the knockout and an icon's stroke width are
   custom properties from design/tokens.css (design/README.md). -->
${symbols.join('\n')}
</svg>
`;
}

